[CmdletBinding()]
param([string]$EvidenceDirectory)
$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$full=Join-Path $root 'scripts/Test-CiFullProof.ps1';$inputScript=Join-Path $root 'scripts/New-CiCostInput.ps1';$reportScript=Join-Path $root 'scripts/Get-TestCostReport.ps1'
$tokens=$null;$errors=$null;[System.Management.Automation.Language.Parser]::ParseFile($full,[ref]$tokens,[ref]$errors)|Out-Null;if($errors.Count){throw "FullProof AST errors: $($errors -join '; ')"}
$base=if($EvidenceDirectory){[IO.Path]::GetFullPath($EvidenceDirectory)}else{Join-Path ([IO.Path]::GetTempPath())('ci36-proof-positive-'+[guid]::NewGuid().ToString('N'))};if(Test-Path -LiteralPath $base){throw "EvidenceDirectory must be new: $base"};$null=New-Item -ItemType Directory -Path $base
$m0=Join-Path $base 'm0-evidence';$null=New-Item -ItemType Directory -Path $m0;$results=Join-Path $m0 'results';$null=New-Item -ItemType Directory -Path $results
$run='manual-run-36';$attempt=1;$code=('a'*40);$candidate=('b'*40);$workflow='refs/workflows/ci.yml';$event='workflow_dispatch';$action='manual';$started='2026-10-24T08:00:00.0000000+00:00';$finished='2026-10-24T08:00:01.2340000+00:00';$wall=1234
function WriteUtf8([string]$Path,[string]$Text){[IO.File]::WriteAllText($Path,$Text,[Text.UTF8Encoding]::new($false))}
function WriteJson([string]$Path,$Value){WriteUtf8 $Path ($Value|ConvertTo-Json -Depth 30)}
WriteJson (Join-Path $base 'fixture.json') @{evidenceKind='synthetic';purpose='Artificial FullProof contract fixture; inner measured fields simulate a completed run, not real M0, CI or performance evidence.'}
$log='test.log';$stdout='test.stdout';$stderr='test.stderr';WriteUtf8 (Join-Path $m0 $log) 'manual command log';WriteUtf8 (Join-Path $m0 $stdout) 'stdout';WriteUtf8 (Join-Path $m0 $stderr) 'stderr';WriteUtf8 (Join-Path $m0 'PASS.txt') 'PASS';WriteUtf8 (Join-Path $m0 'task-exit.txt') '0'
$trxText=@'
<TestRun id="trx-run-36" name="fixture" runUser="fixture" xmlns="http://microsoft.com/schemas/VisualStudio/TeamTest/2010"><Times creation="2026-10-24T08:00:00.0000000+00:00" queuing="2026-10-24T08:00:00.0000000+00:00" start="2026-10-24T08:00:00.1000000+00:00" finish="2026-10-24T08:00:00.9000000+00:00"/><TestSettings name="fixture" id="settings"/><TestDefinitions><UnitTest name="Fixture.Pass" storage="fixture.dll" id="test-1"><Execution id="exec-1"/><TestMethod codeBase="fixture.dll" adapterTypeName="executor://fixture/" className="Fixture.Tests" name="Pass"/></UnitTest></TestDefinitions><TestEntries><TestEntry testId="test-1" executionId="exec-1" testListId="list-1"/></TestEntries><TestLists><TestList name="All Loaded Tests" id="list-1"/></TestLists><Results><UnitTestResult executionId="exec-1" testId="test-1" testName="Fixture.Pass" outcome="Passed" duration="00:00:00.0100000" startTime="2026-10-24T08:00:00.1000000+00:00" endTime="2026-10-24T08:00:00.1100000+00:00"/></Results><ResultSummary outcome="Completed"><Counters total="1" executed="1" passed="1" failed="0" error="0" timeout="0" aborted="0" inconclusive="0" passedButRunAborted="0" notRunnable="0" notExecuted="0" disconnected="0" inProgress="0" pending="0"/><RunInfos/></ResultSummary></TestRun>
'@;WriteUtf8 (Join-Path $results 'one.trx') $trxText
$record=[ordered]@{command='dotnet';arguments=@('test','fixture.csproj','--logger','trx;LogFileName=one.trx','--results-directory','results');log=$log;stdout=$stdout;stderr=$stderr;phase='completed';rootExited=$true;stdoutComplete=$true;stderrComplete=$true;outputComplete=$true;cleanupComplete=$true;exitKnown=$true;cancellationRequested=$false;timedOut=$false;exitCode=0;expectedExit=0;startedUtc=$started;finishedUtc='2026-10-24T08:00:01.0000000+00:00';elapsedMs=$wall}
WriteJson (Join-Path $m0 'commands.json') @($record)
$runId="gha-$run-$attempt";& pwsh -NoProfile -File $inputScript -EvidenceDirectory $m0 -RunId $runId -CodeIdentity $code -TaskExitCode 0 -TaskWallClockMs $wall -OutputPath (Join-Path $m0 'cost-input.json') | Out-Null;if($LASTEXITCODE){throw 'New-CiCostInput failed'}
$reportOut=@(& pwsh -NoProfile -File $reportScript -InputPath (Join-Path $m0 'cost-input.json'));if($LASTEXITCODE -or !$reportOut.Count){throw 'Get-TestCostReport failed'};WriteUtf8 (Join-Path $m0 'cost-report.json') ($reportOut -join "`n");$cost=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json -Depth 60
$identity=[ordered]@{sha=$code;checkout=$code;runId=$run;attempt=$attempt;candidate=$candidate;workflowRef=$workflow;eventName=$event;action=$action};WriteJson (Join-Path $base 'ci-identity.json') $identity
$candidateProof=[ordered]@{eventName=$event;action=$action;mode='manual-full';runId=$run;runAttempt=$attempt;workflowRef=$workflow;draft=$false;headSha=$null;baseSha=$null;candidateSha=$candidate;actualCheckout=$code;tree=('c'*40);parents=[object[]]@()};WriteJson (Join-Path $base 'candidate.json') $candidateProof;WriteJson (Join-Path $base 'end-candidate.json') $candidateProof
$measurement=[ordered]@{schemaVersion=1;measured=$true;runId=$runId;runAttempt=$attempt;codeIdentity=$code;startedUtc=$started;finishedUtc=$finished;wallClockMs=$wall;exitCode=0;exitKnown=$true;evidenceDirectory=$m0;artifacts=@()};$artifactPaths=@('commands.json','PASS.txt','task-exit.txt',$log,$stdout,$stderr,'results/one.trx');foreach($relative in $artifactPaths){$path=Join-Path $m0 $relative;$measurement.artifacts+=,[ordered]@{path=$relative;sha256=(Get-FileHash $path -Algorithm SHA256).Hash;length=([IO.FileInfo]$path).Length}};WriteJson (Join-Path $m0 'task-measurement.json') $measurement
$script:proofCallCount=0
function Invoke-Proof {
 $script:proofCallCount++;$call=Join-Path $base ('calls/'+$script:proofCallCount);$null=New-Item -ItemType Directory -Path $call
 $inputs=Join-Path $call 'inputs';$null=New-Item -ItemType Directory -Path $inputs
 foreach($p in @('ci-identity.json','candidate.json','end-candidate.json')){[IO.File]::Copy((Join-Path $base $p),(Join-Path $inputs $p))}
 foreach($file in Get-ChildItem -LiteralPath $m0 -File -Recurse){$target=Join-Path $inputs ('m0-evidence/'+[IO.Path]::GetRelativePath($m0,$file.FullName));$parent=Split-Path $target -Parent;if(-not(Test-Path $parent)){$null=New-Item -ItemType Directory -Path $parent};[IO.File]::Copy($file.FullName,$target)}
 $argv=@('-NoProfile','-File',$full,'-EvidenceDirectory',$base,'-IdentityPath',(Join-Path $base 'ci-identity.json'),'-CandidateProofPath',(Join-Path $base 'candidate.json'),'-EndCandidateProofPath',(Join-Path $base 'end-candidate.json'),'-ExpectedRunId',$run,'-ExpectedAttempt',$attempt,'-ExpectedCandidate',$candidate,'-ExpectedCodeIdentity',$code,'-ExpectedWorkflowRef',$workflow,'-ExpectedEventName',[string]$identity.eventName,'-ExpectedAction',[string]$identity.action)
 $outFile=Join-Path $call 'proof.stdout';$errFile=Join-Path $call 'proof.stderr';$null=& pwsh @argv 1> $outFile 2> $errFile;$exit=$LASTEXITCODE
 WriteJson (Join-Path $call 'proof-call.json') ([ordered]@{argv=$argv;stdout=$outFile;stderr=$errFile;exit=$exit;sourceSha256=(Get-FileHash $full -Algorithm SHA256).Hash})
 return [pscustomobject]@{Exit=$exit;Stdout=$outFile;Stderr=$errFile;CallDirectory=$call}
}
$modes=@(@{event='workflow_dispatch';action='manual';mode='manual-full';draft=$false;parents=[object[]]@();head=$null;base=$null},@{event='push';action='main';mode='push-main';draft=$false;parents=[object[]]@();head=$null;base=$null},@{event='workflow_dispatch';action='manual';mode='manual-full';draft=$false;parents=[object[]]@(('d'*40));head=$null;base=$null},@{event='push';action='main';mode='push-main';draft=$false;parents=[object[]]@(('d'*40));head=$null;base=$null},@{event='workflow_dispatch';action='manual';mode='manual-full';draft=$false;parents=[object[]]@(('d'*40),('e'*40));head=$null;base=$null},@{event='push';action='main';mode='push-main';draft=$false;parents=[object[]]@(('d'*40),('e'*40));head=$null;base=$null},@{event='pull_request';action='synchronize';mode='ready-full';draft=$false;parents=[object[]]@(('d'*40),('e'*40));head=('e'*40);base=('d'*40)});$passed=0;foreach($modeInfo in $modes){$identity.action=$modeInfo.action;$identity.eventName=$modeInfo.event;$candidateProof.eventName=$modeInfo.event;$candidateProof.action=$modeInfo.action;$candidateProof.mode=$modeInfo.mode;$candidateProof.draft=$modeInfo.draft;$candidateProof.parents=$modeInfo.parents;$candidateProof.headSha=$modeInfo.head;$candidateProof.baseSha=$modeInfo.base;WriteJson (Join-Path $base 'ci-identity.json') $identity;WriteJson (Join-Path $base 'candidate.json') $candidateProof;WriteJson (Join-Path $base 'end-candidate.json') $candidateProof;$result=Invoke-Proof;if($result.Exit -ne 0){throw "FullProof $($modeInfo.mode) positive failed ($($result.Exit)): $([IO.File]::ReadAllText($result.Stderr))"};$proofOutput=Get-Content $result.Stdout -Raw|ConvertFrom-Json;if($proofOutput.status -cne 'complete'){throw "FullProof $($modeInfo.mode) output was not complete"};$passed++}
$matrixRoot=Join-Path $base 'matrix';$null=New-Item -ItemType Directory -Path $matrixRoot;$matrixCount=0
function Run-Mutation([string]$Name,[scriptblock]$Mutate,[string]$ExpectedRegex){$script:matrixCount++;$case=Join-Path $matrixRoot $Name;if(Test-Path $case){throw "Mutation case exists: $case"};$null=New-Item -ItemType Directory -Path $case;$targets=@((Join-Path $base 'ci-identity.json'),(Join-Path $base 'candidate.json'),(Join-Path $base 'end-candidate.json'),(Join-Path $m0 'task-measurement.json'),(Join-Path $m0 'cost-input.json'),(Join-Path $m0 'cost-report.json'));$saved=@{};foreach($target in $targets){$saved[$target]=[IO.File]::ReadAllText($target,[Text.UTF8Encoding]::new($false,$true))};try{& $Mutate;$r=Invoke-Proof;$err=[IO.File]::ReadAllText($r.Stderr);$out=[IO.File]::ReadAllText($r.Stdout);WriteUtf8 (Join-Path $case 'mutation.json') (@{name=$Name;expected=$ExpectedRegex;exit=$r.Exit;callDirectory=$r.CallDirectory}|ConvertTo-Json);WriteUtf8 (Join-Path $case 'raw.stdout') $out;WriteUtf8 (Join-Path $case 'raw.stderr') $err;if($r.Exit -eq 0 -or $err -notmatch $ExpectedRegex){throw "Mutation $Name expected nonzero stage $ExpectedRegex, got exit $($r.Exit): $err"}}finally{foreach($target in $targets){WriteUtf8 $target $saved[$target]}}}
Run-Mutation 'wrong-cost-run' { $x=Get-Content (Join-Path $m0 'cost-input.json') -Raw|ConvertFrom-Json;$x.runId='gha-old-1';WriteJson (Join-Path $m0 'cost-input.json') $x } '\[full-proof:cost\]'
Run-Mutation 'wrong-code' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.sha=('f'*40);WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:identity\]'
Run-Mutation 'synthetic-cost' { $x=Get-Content (Join-Path $m0 'cost-input.json') -Raw|ConvertFrom-Json;$x.evidenceKind='synthetic';WriteJson (Join-Path $m0 'cost-input.json') $x } '\[full-proof:cost\]'
Run-Mutation 'missing-schema' { $x=Get-Content (Join-Path $m0 'cost-input.json') -Raw|ConvertFrom-Json;$x.PSObject.Properties.Remove('schemaVersion');WriteJson (Join-Path $m0 'cost-input.json') $x } '\[full-proof:type\]'
Run-Mutation 'measurement-exit-string' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.exitCode='0';WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'measurement-exit-known-false' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.exitKnown=$false;WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'outer-exit-seven' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.exitCode=7;WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:original-task\]'
Run-Mutation 'artifact-hash-tamper' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.artifacts[0].sha256=('0'*64);WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:artifact\]'
Run-Mutation 'wrong-commands-path' { $x=Get-Content (Join-Path $m0 'cost-input.json') -Raw|ConvertFrom-Json;$x.commandsPath='other-commands.json';WriteJson (Join-Path $m0 'cost-input.json') $x } '\[full-proof:cost\]'
Run-Mutation 'draft-candidate' { $x=Get-Content (Join-Path $base 'candidate.json') -Raw|ConvertFrom-Json;$x.draft=$true;WriteJson (Join-Path $base 'candidate.json') $x } '\[full-proof:identity\]'
Run-Mutation 'wrong-workflow' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.workflowRef='refs/workflows/wrong.yml';WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:identity\]'
Run-Mutation 'candidate-tree-diff' { $x=Get-Content (Join-Path $base 'end-candidate.json') -Raw|ConvertFrom-Json;$x.tree=('9'*40);WriteJson (Join-Path $base 'end-candidate.json') $x } '\[full-proof:identity\]'
Run-Mutation 'candidate-singleton-array' { $x=Get-Content (Join-Path $base 'candidate.json') -Raw;WriteUtf8 (Join-Path $base 'candidate.json') ('['+$x.Trim()+']') } '\[full-proof:type\]'
Run-Mutation 'negative-wall' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.wallClockMs=-1;WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'fraction-artifact-length' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.artifacts[0].length+=0.1;WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'no-zone-measurement' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json -DateKind String;$x.startedUtc=[DateTimeOffset]::Parse($x.startedUtc).ToLocalTime().DateTime.ToString('yyyy-MM-ddTHH:mm:ss.fffffff');$x.finishedUtc=[DateTimeOffset]::Parse($x.finishedUtc).ToLocalTime().DateTime.ToString('yyyy-MM-ddTHH:mm:ss.fffffff');WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'identity-candidate' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.candidate=('f'*40);WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:identity\]'
Run-Mutation 'measurement-root' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.evidenceDirectory=Join-Path $base 'other-owned-root';WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'capture-error' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x|Add-Member -NotePropertyName captureErrors -NotePropertyValue @('controlled capture error');WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'cost-code' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.context.codeIdentity=('f'*40);WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:identity\]'
Run-Mutation 'identity-run' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.runId='wrong-run';WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:identity\]'
Run-Mutation 'identity-attempt' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.attempt=2;WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:identity\]'
Run-Mutation 'missing-commands' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.PSObject.Properties.Remove('commands');WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:cost\]'
Run-Mutation 'missing-artifacts' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.PSObject.Properties.Remove('artifacts');WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:cost\]'
Run-Mutation 'cost-exit-string' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.taskResult.exitCode='0';WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:type\]'
Run-Mutation 'cost-exit-boolean' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.taskResult.exitCode=$false;WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:type\]'
Run-Mutation 'command-outside-outer-window' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json -DateKind String;$x.commands[0].originalRecord.finishedUtc='2026-10-24T08:00:10.0000000+00:00';WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:measurement\]'
Run-Mutation 'boolean-wall' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.wallClockMs=$true;WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'string-wall' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.wallClockMs='1234';WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'historical-report' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.evidenceKind='historical';WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:cost\]'
Run-Mutation 'null-parents' { $x=Get-Content (Join-Path $base 'candidate.json') -Raw|ConvertFrom-Json;$x.parents=$null;WriteJson (Join-Path $base 'candidate.json') $x } '\[full-proof:identity\]'
Run-Mutation 'scalar-parents' { $x=Get-Content (Join-Path $base 'candidate.json') -Raw|ConvertFrom-Json;$x.parents=('d'*40);WriteJson (Join-Path $base 'candidate.json') $x } '\[full-proof:identity\]'
Run-Mutation 'array-identity-code' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.sha=@($code);WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:type\]'
Run-Mutation 'array-identity-attempt' { $x=Get-Content (Join-Path $base 'ci-identity.json') -Raw|ConvertFrom-Json;$x.attempt=@(1);WriteJson (Join-Path $base 'ci-identity.json') $x } '\[full-proof:type\]'
Run-Mutation 'array-exit' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.exitCode=@(0);WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'array-exit-known' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.exitKnown=@($true);WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:type\]'
Run-Mutation 'scalar-commands' { $x=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json;$x.commands=$x.commands[0];WriteJson (Join-Path $m0 'cost-report.json') $x } '\[full-proof:cost\]'
Run-Mutation 'scalar-artifacts' { $x=Get-Content (Join-Path $m0 'task-measurement.json') -Raw|ConvertFrom-Json;$x.artifacts=$x.artifacts[0];WriteJson (Join-Path $m0 'task-measurement.json') $x } '\[full-proof:measurement\]'
$reordered=[ordered]@{};foreach($name in @('parents','tree','actualCheckout','candidateSha','baseSha','headSha','draft','mode','action','eventName','workflowRef','runAttempt','runId')){$reordered[$name]=$candidateProof.$name};WriteJson (Join-Path $base 'candidate.json') $reordered;WriteJson (Join-Path $base 'end-candidate.json') $reordered;$reorderedResult=Invoke-Proof;if($reorderedResult.Exit -ne 0){throw 'FullProof reordered candidate positive failed'}
if((Get-Content $reorderedResult.Stdout -Raw|ConvertFrom-Json).status -cne 'complete'){throw 'Reordered candidate did not return complete'}
$storedCost=Get-Content (Join-Path $m0 'cost-report.json') -Raw|ConvertFrom-Json -Depth 100 -DateKind String
$costKeys=@($storedCost.PSObject.Properties.Name);[Array]::Reverse($costKeys);$reorderedCost=[ordered]@{};foreach($key in $costKeys){$reorderedCost[$key]=$storedCost.$key}
WriteJson (Join-Path $m0 'cost-report.json') $reorderedCost
$costReorderedResult=Invoke-Proof;if($costReorderedResult.Exit -ne 0 -or (Get-Content $costReorderedResult.Stdout -Raw|ConvertFrom-Json).status -cne 'complete'){throw 'Semantically equivalent reordered cost report was rejected'}
Write-Output "PASS FullProof complete positive modes: $passed/7 (manual/push parents 0/1/2, ready-full), reordered=2 (candidate/report), mutations=${matrixCount}: $base"
if(-not $EvidenceDirectory){Remove-Item -LiteralPath $base -Recurse -Force}
